// Recovery assurance helper: pass count against target, coverage and the first four active tests.
// Runs on records.onDataQuerySuccess, masters.onDataQuerySuccess and Recovery assurance onPageLoad.
const rows = queries.records.data || [], services = queries.masters.data || [];
const active = rows.filter(r => !['Complete', 'Completed', 'Closed'].includes(r.status || 'Open'));
const plan = p => (p.decisions || []).filter(d => d.type === 'plan').slice(-1)[0] || {};
const result = p => (p.decisions || []).filter(d => d.type === 'result' && d.version === plan(p).version).slice(-1)[0] || {};
// owner's decision: a passed drill = restore time within the service's allowed minutes, data loss within the plan's RPO, reference present
const passed = p => {
  const r = result(p), v = plan(p), s = services.find(x => x.name === p.context) || {};
  return r.type === 'result' && Number.isFinite(Number(r.restore)) && Number(r.restore) <= Number(s.capacity || 0)
    && Number.isFinite(Number(r.loss)) && Number(r.loss) <= Number(v.rpo) && String(r.reference || '').trim().length >= 3;
};
const pass = rows.filter(passed).length;
return {
  total: rows.length,
  passLabel: pass + '/' + rows.length,
  passPct: rows.length ? Math.round(pass / rows.length * 100) : 0,
  rows: active.slice(0, 4).map(r => ({ id: r.id, title: r.name || 'Untitled', owner: r.owner || 'Unassigned', status: r.status || 'Open', due: r.due || '' }))
};

// Test execution helper: the selected record's summary fields, reviews, plan outcome and history.
// Runs on records.onDataQuerySuccess and Test execution onPageLoad.
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const dec = (p && p.decisions) || [];
const plan = dec.filter(d => d.type === 'plan').slice(-1)[0] || {};
const result = dec.filter(d => d.type === 'result' && d.version === plan.version).slice(-1)[0] || {};
const review = role => dec.filter(d => d.type === 'review' && d.role === role && d.version === plan.version).slice(-1)[0] || null;
const pick = q => q ? { decision: q.decision || '', reviewer: q.reviewer || '', note: q.note || '' } : null;
const outcomeLine = result.type ? Object.entries(result).filter(([k]) => !['type', 'version', 'at'].includes(k)).map(([k, v]) => k.replace(/([A-Z])/g, ' $1') + ': ' + String(v)).join(' · ') : '';
const history = ((p && p.history) || []).slice().reverse().map(h => ({
  lineHtml: '<b>' + e(h.event) + '</b> <span style="color:var(--cc-placeholder-text);">' + e(String(h.at || '').slice(0, 16).replace('T', ' ')) + '</span>',
  note: h.note || ''
}));
return {
  has: !!p,
  context: (p && p.context) || '',
  status: (p && p.status) || '',
  ownerPlan: p ? ((p.owner || '') + ' · Plan ' + (plan.version || '—')) : '',
  backupText: plan.backup != null ? String(plan.backup) : 'Not recorded',
  rpoText: plan.rpo != null ? String(plan.rpo) : 'Not recorded',
  reviewA: pick(review('Recovery owner')),
  reviewB: pick(review('Service owner')),
  outcomeLine,
  history: history.length ? history : [{ lineHtml: '', note: 'Select a record to inspect its saved activity.' }]
};
